#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

struct Edge {
    int u, v;
    long long cap, flow;
    long long cst;
    long long remaining() { return cap - flow; }
    Edge() {}
    Edge(int _u, int _v, long long _cap, long long _flow, long long _cst)
        : u(_u), v(_v), cap(_cap), flow(_flow), cst(_cst) {}
};

int total_nodes;
vector<int> adj[8200];
vector<Edge> all_edges;

void create_edge(int u, int v, long long cap, long long cst) {
    adj[u].push_back((int)all_edges.size());
    all_edges.emplace_back(u, v, cap, 0, cst);
    adj[v].push_back((int)all_edges.size());
    all_edges.emplace_back(v, u, 0, 0, -cst);
}

long long dist[8200], total_cost;
int parent[8200];
long long flow_cap[8200], total_flow;
bool in_q[8200];

void min_cost_max_flow(int s, int t) {
    memset(in_q, 0, sizeof(in_q));
    total_flow = total_cost = 0;
    while (true) {
        fill(dist, dist + total_nodes, 1e15);
        dist[s] = 0;
        memset(parent, -1, sizeof(parent));
        parent[s] = 0;
        memset(flow_cap, 0, sizeof(flow_cap));
        flow_cap[s] = 1e15;
        queue<int> q;
        q.push(s);
        in_q[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_q[u] = false;
            for (int idx : adj[u]) {
                Edge &e = all_edges[idx];
                if (e.remaining() > 0 && dist[e.v] > dist[u] + e.cst + 1e-9) {
                    dist[e.v] = dist[u] + e.cst;
                    parent[e.v] = idx;
                    flow_cap[e.v] = min(flow_cap[u], e.remaining());
                    if (!in_q[e.v]) {
                        q.push(e.v);
                        in_q[e.v] = true;
                    }
                }
            }
        }
        if (parent[t] < 0) break;
        total_flow += flow_cap[t];
        total_cost += flow_cap[t] * dist[t];
        for (int v = t; v != s; v = all_edges[parent[v]].u) {
            all_edges[parent[v]].flow += flow_cap[t];
            all_edges[parent[v] ^ 1].flow -= flow_cap[t];
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x; x--;
        create_edge(0, x + 1, 1, 0);
    }
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; x--; y--;
        for (int i = 0; i < 105; i++) {
            for (int j = 0; j < 51; j++) {
                create_edge(i * n + x + 1, (i + 1) * n + y + 1, 1, c + d * (2 * j + 1));
                create_edge(i * n + y + 1, (i + 1) * n + x + 1, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i < 105; i++) {
        for (int j = 0; j < n; j++) {
            create_edge(i * n + j + 1, (i + 1) * n + j + 1, 51, c);
        }
    }
    for (int i = 0; i < 105; i++) {
        create_edge(i * n + 1, 105 * n + 1, 51, 0);
    }
    total_nodes = 6 + 107 * n;
    min_cost_max_flow(0, 105 * n + 1);
    cout << total_cost << "\n";
    return 0;
}
